select customers.customer_id, customer_name from customers join orders on customers.customer_id = orders.customer_id group by customers.customer_id, customers.customer_name having sum(case when orders.product_name = 'A' then 1 else 0 end) >0 and sum(case when orders.product_name = 'B' then 1 else 0 end) > 0 and sum(case when orders.product_name = 'C' then 1 else 0 end) =0 order by customers.customer_name;